<?php $e = static fn (mixed $v): string => App\Core\View::e($v); $csrf = App\Core\Security::csrfToken(); ?>
<section class="page-stack"><div class="section-heading"><div><p class="eyebrow"><?= $e($match['championship_name']) ?></p><h1>Evidências da partida</h1><p><?= $e($match['home_team_name']) ?> x <?= $e($match['away_team_name']) ?></p></div><a class="button secondary" href="<?= $e(App\Core\Config::url('/admin/partidas/' . $match['id'] . '/operacao')) ?>">Central operacional</a></div><?php if (!empty($message)): ?><p class="success"><?= $e($message) ?></p><?php endif; ?><?php if ($canUpload): ?><article class="panel"><h2>Enviar fotografia</h2><form method="post" enctype="multipart/form-data" class="form-grid" action="<?= $e(App\Core\Config::url('/admin/partidas/' . $match['id'] . '/evidencias')) ?>"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><label>Título <input name="title" maxlength="180" required></label><label>Visibilidade <select name="visibility"><option value="accountability">Prestação de contas</option><option value="private">Privada</option><option value="public">Pública</option></select></label><label>Data e hora <input type="datetime-local" name="captured_at"></label><label>Foto <input type="file" name="photo" accept="image/png,image/jpeg,image/webp" required><small>O sistema reduz, corrige e salva em WebP automaticamente.</small></label><label>Legenda <textarea name="caption" maxlength="500"></textarea></label><button type="submit">Enviar evidência</button></form></article><?php endif; ?><div class="media-grid"><?php foreach ($items as $item): ?><article class="panel media-card"><img src="<?= $e(App\Core\Config::url('/admin/partidas/' . $match['id'] . '/evidencias/' . $item['id'])) ?>" alt="<?= $e($item['title']) ?>"><h2><?= $e($item['title']) ?></h2><p><?= $e($item['caption'] ?: 'Sem legenda.') ?></p><small><?= $e($item['visibility']) ?> · <?= $e($item['created_at']) ?></small></article><?php endforeach; ?></div></section>
